--
-- Name: cargo_trips; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.cargo_trips (
    id integer NOT NULL,
    vehicle_id integer NOT NULL,
    plate_number text NOT NULL,
    departure_time timestamp with time zone NOT NULL,
    return_time timestamp with time zone,
    origin text,
    destination text,
    fuel_liters numeric(12,2),
    fuel_price_per_liter numeric(14,2),
    fuel_cost_total numeric(14,2) GENERATED ALWAYS AS ((fuel_liters * fuel_price_per_liter)) STORED,
    freight_revenue numeric(14,2),
    distance_km numeric(12,2),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    invoice_date date,
    company_id integer,
    vat_rate numeric(5,4),
    payment_method character varying(16),
    payment_status character varying(20) DEFAULT 'paid'::character varying,
    debt_amount numeric(14,2) DEFAULT 0,
    invoice_bill_number bigint,
    service_name text DEFAULT 'Cước vận chuyển'::text NOT NULL,
    document_number text,
    driver_name text,
    cargo_description text,
    trip_quantity numeric(8,2),
    cargo_weight_tons numeric(12,3),
    trip_wage numeric(16,2),
    trip_other_cost numeric(16,2),
    trip_note text,
    odometer_end numeric(14,1),
    vehicle_owner_type text,
    outsourced_freight numeric(16,2),
    source_ref text,
    source_revenue_gross numeric(16,2),
    qr_url text,
    seller_company_id integer,
    route_segments jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT cargo_trips_payment_method_allowed CHECK (((payment_method IS NULL) OR ((payment_method)::text = ANY ((ARRAY['CK'::character varying, 'TM'::character varying, 'TM/CK'::character varying, 'UNKNOWN'::character varying])::text[])))),
    CONSTRAINT cargo_trips_vat_rate_allowed CHECK (((vat_rate IS NULL) OR ((vat_rate >= (0)::numeric) AND (vat_rate <= (1)::numeric))))
);


ALTER TABLE public.cargo_trips OWNER TO postgres;

