    vendor text,
    invoice_number text,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    source_ref text,
    CONSTRAINT vehicle_expenses_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT vehicle_expenses_expense_type_check CHECK ((expense_type = ANY (ARRAY['fuel'::text, 'repair'::text, 'toll'::text, 'other'::text]))),
    CONSTRAINT vehicle_expenses_quantity_check CHECK (((quantity IS NULL) OR (quantity >= (0)::numeric))),
    CONSTRAINT vehicle_expenses_unit_price_check CHECK (((unit_price IS NULL) OR (unit_price >= (0)::numeric)))
);


ALTER TABLE public.vehicle_expenses OWNER TO postgres;

